import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Grok Business & Enterprise","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/grok/grok-business.md","filePath":"zh/products/ai-coding/grok/grok-business.md","lastUpdated":1787107158000}'),s={name:"zh/products/ai-coding/grok/grok-business.md"};function n(i,r,l,d,g,h){return a(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="grok-business-enterprise" tabindex="-1">Grok Business &amp; Enterprise <a class="header-anchor" href="#grok-business-enterprise" aria-label="Permalink to &quot;Grok Business &amp; Enterprise&quot;">​</a></h1><blockquote><p>官方定位（<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a>）： &quot;<strong>Grok Business provides dedicated workspaces for personal and team use, with enhanced privacy and sharing controls.</strong>&quot;</p><p><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a> 把 <strong>Business &amp; Enterprise</strong> 列为一级下一步：&quot;team workspaces, licenses, and organization controls.&quot;</p><p>本页给这个官方入口画产品地图。在本站复杂度轴上它比 Grok Build 靠后。仍然立页，因为 xAI 把它放在 Grok 文档首页。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 公司已经有（或正在买）Grok Business / Enterprise 的人，不是个人 SuperGrok 订阅者。</p><p><strong>目标：</strong> 讲清个人 / 团队工作区、许可证、分享、管理控制台。指向官方页。</p><p><strong>非目标：</strong> 臆造席位价格、再抄一遍企业法律条款，或 Grok Build 的 <code>/etc/grok/requirements.toml</code> 策略（那是 <a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">CLI 企业策略</a>，另一个产品）。</p><h2 id="你得到什么" tabindex="-1">你得到什么 <a class="header-anchor" href="#你得到什么" aria-label="Permalink to &quot;你得到什么&quot;">​</a></h2><p>一个<strong>团队工作区</strong>（<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>）：</p><ul><li>隐私保证见 xAI 的 <a href="https://x.ai/legal/terms-of-service-enterprise" target="_blank" rel="noreferrer">企业条款</a>。</li><li>完整 <strong>SuperGrok</strong> 能力（升级许可证则是 <strong>SuperGrok Heavy</strong>）。</li><li>对话只能安全分享给<strong>有有效许可证</strong>的团队成员。</li></ul><p>两种工作区：</p><table tabindex="0"><thead><tr><th>工作区</th><th>给谁</th><th>门槛</th></tr></thead><tbody><tr><td><strong>Personal</strong></td><td>个人使用</td><td>默认有；组织可在 Enterprise 许可证上关掉</td></tr><tr><td><strong>Team</strong></td><td>团队协作</td><td>必须有<strong>有效许可证</strong></td></tr></tbody></table><p>在 grok.com <strong>左下角</strong>导航切换工作区。开新对话前先确认你在正确的工作区。</p><p>打不开团队工作区 = 没有有效许可证，找团队管理员。<strong>看不见个人工作区</strong> = 组织关掉了；开关这件事走 Enterprise / 销售（<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>）。</p><p>Enterprise 另有自定义保留策略。本页不转述法律条文——读 <a href="https://x.ai/legal/terms-of-service-enterprise" target="_blank" rel="noreferrer">x.ai/legal/terms-of-service-enterprise</a>。</p><h2 id="许可证与用户" tabindex="-1">许可证与用户 <a class="header-anchor" href="#许可证与用户" aria-label="Permalink to &quot;许可证与用户&quot;">​</a></h2><p>枢纽： <a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a> 的 Grok Business 总览（<a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">management</a>、<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>）。</p><p>官方许可证类型（<a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">management</a>）：</p><ul><li><strong>SuperGrok</strong> — 标准商务访问，更高配额与功能。</li><li><strong>SuperGrok Heavy</strong> — 面向更重负载的升级性能。</li></ul><p>本页<strong>不</strong>臆造每席美元价。</p><p>管理员流程（压缩自 <a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">management</a> 与 <a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>）：</p><ol><li>在总览页购买许可证（类型 + 数量）。需要 <strong>Billing Read-Write</strong>。</li><li>用邮箱邀请用户；可选在接受时自动配发许可证。需要 <strong>Team Read-Write</strong>。被邀请者获得团队工作区访问与基础 team read（这样才能分享对话）。</li><li>在用户列表里分配 / 收回许可证。收回后许可证回池，<strong>团队</strong>工作区权限取消；<strong>个人</strong>工作区仍在。</li><li>在总览页取消未用许可证。取消可能要几天；符合条件的退款回到原支付方式。</li></ol><p>终端用户开通（<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>）：console.x.ai → <strong>Assign license</strong> → 选类型。然后 grok.com 上会出现团队工作区。</p><h2 id="分享" tabindex="-1">分享 <a class="header-anchor" href="#分享" aria-label="Permalink to &quot;分享&quot;">​</a></h2><p>团队对话分享（<a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">user-guide</a>）：</p><ol><li>在<strong>团队工作区</strong>打开对话。</li><li>分享按钮 → 选择团队成员 → 生成链接。</li><li>链接只对<strong>有许可证</strong>的团队成员可开。非成员、未授权队友打不开。</li><li>收件箱：<a href="https://grok.com/history?tab=shared-with-me" target="_blank" rel="noreferrer">grok.com/history?tab=shared-with-me</a>。</li></ol><p>组织级分享策略是<strong>上限</strong>，不是默认全员分享（<a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">management</a>）。管理员在 console.x.ai → <strong>Sharing &amp; Retention</strong> → <strong>Product Sharing</strong> 设置。每种资源单独一条：conversations、projects、skills。</p><table tabindex="0"><thead><tr><th>级别</th><th>成员能做什么</th></tr></thead><tbody><tr><td><strong>Private</strong></td><td>该资源关闭分享</td></tr><tr><td><strong>Team</strong></td><td>个别队友与成员自己的团队。不能全组织 / 跨团队</td></tr><tr><td><strong>Organization</strong></td><td>Team，再加上其他团队和全组织</td></tr><tr><td><strong>Public</strong></td><td>Organization，再加上任何人都能打开的公开链接</td></tr></tbody></table><p>公开链接<strong>只适用于对话</strong>。projects 与 skills 最高到 Organization。默认：对话和项目可组织范围分享；<strong>skills 默认 Private</strong>。收紧策略立即生效，已经超出新上限的旧分享也会被压下来。</p><h2 id="团队里的-connectors" tabindex="-1">团队里的 Connectors <a class="header-anchor" href="#团队里的-connectors" aria-label="Permalink to &quot;团队里的 Connectors&quot;">​</a></h2><p>Business / Enterprise 成员<strong>不能</strong>自己先加 connector。必须由团队管理员在控制台开通，然后成员在 <a href="https://grok.com/connectors" target="_blank" rel="noreferrer">grok.com/connectors</a> 连接自己的账号。细节见 <a href="./grok-connectors.html">Connectors</a> 与 <a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">connector-management</a>。</p><h2 id="不是本页" tabindex="-1">不是本页 <a class="header-anchor" href="#不是本页" aria-label="Permalink to &quot;不是本页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>为什么不同</th></tr></thead><tbody><tr><td>grok.com 上的个人 SuperGrok</td><td>没有团队工作区，没有许可证池。见 <a href="./grok-chat.html">Grok 聊天</a></td></tr><tr><td>消费端 <a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a> 里的 xAI API「teams」</td><td>控制台里给 <strong>API 用量 / 发票</strong> 用的团队，不是 Grok Business 工作区</td></tr><tr><td>Grok Build 企业策略</td><td>CLI 上的五层配置、OIDC、MDM（<a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">docs.x.ai/build/enterprise</a>）</td></tr><tr><td>Grok Bot 团队</td><td>每人一台云电脑（<a href="https://docs.x.ai/grok-bot/teams-and-enterprises" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/teams-and-enterprises</a>）</td></tr></tbody></table><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li>机密对话开在<strong>个人</strong>工作区，然后奇怪团队分享链接不生效。</li><li>指望没许可证的队友能打开分享链接。官方写明不能。</li><li>把 Grok Business 许可证和 <code>XAI_API_KEY</code> 的 API credit 当成同一口池。</li><li>在本页找席位价格。官方文档列的是<strong>许可证类型</strong>，没有消费级美元数字。</li></ul><h2 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>用来干什么</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/grok/user-guide" target="_blank" rel="noreferrer">docs.x.ai/grok/user-guide</a></td><td>工作区、隐私、对话分享、激活许可证</td></tr><tr><td><a href="https://docs.x.ai/grok/management" target="_blank" rel="noreferrer">docs.x.ai/grok/management</a></td><td>购买 / 邀请 / 分配 / 收回 / 取消，分享策略</td></tr><tr><td><a href="https://docs.x.ai/grok/connector-management" target="_blank" rel="noreferrer">docs.x.ai/grok/connector-management</a></td><td>管理员开通 connectors</td></tr><tr><td><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a></td><td>一级「Business &amp; Enterprise」入口</td></tr><tr><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td><td>管理枢纽</td></tr><tr><td><a href="https://x.ai/legal/terms-of-service-enterprise" target="_blank" rel="noreferrer">企业条款</a></td><td>隐私 / 数据处理</td></tr></tbody></table><p>白手套 / Enterprise 升级：联系 xAI 销售（文档页把地址做成站点控件）。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./grok-chat.html">Grok 聊天</a> — 成员在工作区里用的东西</li><li><a href="./grok-connectors.html">Connectors</a> — 管理员开通 + 成员 OAuth</li><li><a href="./grok-bot.html">Grok Bot</a> — 另一套团队产品</li><li><a href="./grok-cli.html">Grok Build 教程</a> — CLI 企业策略在别处</li><li><a href="./">Grok 学习地图</a></li></ul>',39)])])}const m=t(s,[["render",n]]);export{f as __pageData,m as default};
